"use strict";
import { useQuery } from "@tanstack/react-query";
import { Contract } from "@ethersproject/contracts";
import { BigNumber } from "@ethersproject/bignumber";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useUserGaugeData } from "./useGaugeData";
const V2_PAIR_ABI = [
  {
    constant: true,
    inputs: [],
    name: "token0",
    outputs: [{ name: "", type: "address" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "token1",
    outputs: [{ name: "", type: "address" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "getReserves",
    outputs: [
      { name: "reserve0", type: "uint112" },
      { name: "reserve1", type: "uint112" },
      { name: "blockTimestampLast", type: "uint32" }
    ],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "totalSupply",
    outputs: [{ name: "", type: "uint256" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [{ name: "", type: "address" }],
    name: "balanceOf",
    outputs: [{ name: "", type: "uint256" }],
    type: "function"
  }
];
const TOKEN_ABI = [
  {
    constant: true,
    inputs: [],
    name: "symbol",
    outputs: [{ name: "", type: "string" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "name",
    outputs: [{ name: "", type: "string" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "decimals",
    outputs: [{ name: "", type: "uint8" }],
    type: "function"
  }
];
const GAUGE_ABI = [
  {
    constant: true,
    inputs: [{ name: "", type: "address" }],
    name: "balanceOf",
    outputs: [{ name: "", type: "uint256" }],
    type: "function"
  }
];
export function useV2PositionDeduped(poolAddress, chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  const { data: userGaugeData, isLoading: isLoadingGaugeData } = useUserGaugeData();
  return useQuery({
    queryKey: ["v2-position-deduped", poolAddress, account.address, chainId, userGaugeData?.stakes?.length],
    queryFn: async () => {
      if (!poolAddress || !provider || !account.address) return null;
      try {
        const pairContract = new Contract(poolAddress, V2_PAIR_ABI, provider);
        const [
          token0Address,
          token1Address,
          reserves,
          totalSupply,
          walletBalance
        ] = await Promise.all([
          pairContract.token0(),
          pairContract.token1(),
          pairContract.getReserves(),
          pairContract.totalSupply(),
          pairContract.balanceOf(account.address)
        ]);
        const token0Contract = new Contract(token0Address, TOKEN_ABI, provider);
        const token1Contract = new Contract(token1Address, TOKEN_ABI, provider);
        const [
          token0Symbol,
          token0Name,
          token0Decimals,
          token1Symbol,
          token1Name,
          token1Decimals
        ] = await Promise.all([
          token0Contract.symbol(),
          token0Contract.name(),
          token0Contract.decimals(),
          token1Contract.symbol(),
          token1Contract.name(),
          token1Contract.decimals()
        ]);
        let gaugeBalance = BigNumber.from(0);
        let gaugeAddress;
        if (userGaugeData?.stakes && poolAddress) {
          const stake = userGaugeData.stakes.find(
            (stake2) => stake2.gauge.pool.toLowerCase() === poolAddress.toLowerCase()
          );
          if (stake) {
            gaugeAddress = stake.gauge.id;
            gaugeBalance = BigNumber.from(stake.amount || "0");
          }
        }
        if (gaugeAddress && provider) {
          try {
            const gaugeContract = new Contract(gaugeAddress, GAUGE_ABI, provider);
            const contractBalance = await gaugeContract.balanceOf(account.address);
            if (contractBalance) {
              gaugeBalance = contractBalance;
            }
          } catch (error) {
            console.warn("Failed to fetch gauge balance from contract:", error);
          }
        }
        const walletBalanceBN = BigNumber.from(walletBalance);
        const totalBalance = walletBalanceBN.add(gaugeBalance);
        const hasWalletBalance = walletBalanceBN.gt(0);
        const hasStakedBalance = gaugeBalance.gt(0);
        const isPartiallyStaked = hasWalletBalance && hasStakedBalance;
        const isFullyStaked = !hasWalletBalance && hasStakedBalance;
        const isUnstaked = hasWalletBalance && !hasStakedBalance;
        let stakingPercentage = 0;
        if (totalBalance.gt(0)) {
          stakingPercentage = gaugeBalance.mul(100).div(totalBalance).toNumber();
        }
        const position = {
          type: "v2",
          poolAddress,
          token0: {
            id: token0Address.toLowerCase(),
            symbol: token0Symbol,
            name: token0Name,
            decimals: token0Decimals.toString()
          },
          token1: {
            id: token1Address.toLowerCase(),
            symbol: token1Symbol,
            name: token1Name,
            decimals: token1Decimals.toString()
          },
          // Use total balance (wallet + staked) as the main balance
          balance: totalBalance.toString(),
          totalSupply: totalSupply.toString(),
          reserve0: reserves.reserve0.toString(),
          reserve1: reserves.reserve1.toString(),
          reserveUSD: "0",
          // Would need price data to calculate
          stable: false,
          // Abstract DEX V2 pools are all volatile
          // Staking status fields
          isStaked: isFullyStaked,
          hasGaugeStake: hasStakedBalance,
          gaugeAddress,
          gaugeStakeAmount: gaugeBalance.toString(),
          // Partial staking fields
          isPartiallyStaked,
          stakedAmount: gaugeBalance.toString(),
          unstakedAmount: walletBalanceBN.toString(),
          stakingPercentage,
          // Combined totals
          totalBalance: totalBalance.toString(),
          totalBalanceFormatted: (parseFloat(totalBalance.toString()) / 1e18).toFixed(6)
        };
        return position;
      } catch (error) {
        console.error("Failed to fetch deduplicated V2 position:", error);
        return null;
      }
    },
    enabled: !!poolAddress && !!provider && !!account.address && !isLoadingGaugeData,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
}
